      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, []);

  useEffect(() => {
    const element = rootEl.current;
    const scene = source?.current;
    const host = mirrorHost.current;
    if (
      !element ||
      !scene ||
      !host ||
      !sceneCovered ||
      reduced ||
      !budgetActive ||
      rendering !== "auto"
    ) {
      setSceneReady(false);
      return;
    }
    const subscription = attachSceneMirror(scene, host, element, samplingPad, {
      frameRate:
        frameRate ?? context?.frameRate ?? settings.performance?.frameRate,
      onPaint: () => {
        manager.current?.refresh();
        if (adaptiveBackdrop)
          setBackdropKind(classifyGlassBackdrop(scene, element));
      },
    });
    mirror.current = subscription;
    setSceneReady(true);
    return () => {
      subscription.destroy();
      mirror.current = null;
    };
  }, [
    source,
    sceneCovered,
    reduced,
    budgetActive,
    samplingPad,
    frameRate,
    context?.frameRate,
    settings.performance?.frameRate,
    adaptiveBackdrop,
    rendering,
  ]);

  useEffect(() => {
    if (!refractive || size.w < 2 || size.h < 2) return;
    let cancelled = false;
    const frame = requestAnimationFrame(() => {
      const next = buildLensTextures(fw, fh, {
        radius: Math.min(safeRadius, size.w / 2, size.h / 2),
        splay: p.splay,
        feather: p.feather,
        curve: p.curve,
        pad: samplingPad,
        optics: optical,
        shape,
        deformation:
          pullX === undefined && pullY === undefined
            ? undefined
