    });
    return () => {
      cancelled = true;
      cancelAnimationFrame(frame);
    };
  }, [
    refractive,
    size.w,
    size.h,
    fw,
    fh,
    safeRadius,
    samplingPad,
    optical,
    p.splay,
    p.feather,
    p.curve,
    shape,
    pullX,
    pullY,
  ]);

  const { blur: resolvedBlur, depth: resolvedDepth } = resolveBackdropTreatment(
    backdropKind,
    p,
    adaptiveBackdrop,
    preserveBlur,
  );
  const colorFinish = `saturate(${p.saturate})${p.brightness !== 1 ? ` brightness(${p.brightness})` : ""}${p.contrast !== 1 ? ` contrast(${p.contrast})` : ""}`;
  const diffuse = `${resolvedBlur > 0 ? `blur(${resolvedBlur}px) ` : ""}${colorFinish}`;
  useLayoutEffect(() => {
    if (!housing.current || !layer.current) return;
    manager.current?.destroy();
    manager.current = null;
    if (!active || !map) return;
