    position: "absolute",
    inset: -samplingPad,
    backgroundSize: "100% 100%",
    backgroundRepeat: "no-repeat",
    opacity: p.glint / 100,
  };
  const mode =
    rendering === "inherited"
      ? "inherited"
      : settings.refraction === false
        ? "disabled"
        : rendering === "composited"
          ? compositorReady
            ? "scene-atlas"
            : "css"
          : reduced
            ? "opaque"
            : active
              ? sceneReady
                ? "scene-svg"
                : plane
                  ? "source-svg"
                  : "backdrop-svg"
              : "css";
