    <Tag
      {...rest}
      ref={setRoot}
      className={cn("relative isolate", className)}
      data-liquid-glass=""
      data-glass-shape={shape}
      data-glass-scene-coverage={
        requireSceneCoverage
          ? sceneCovered
            ? "inside"
            : "outside"
          : "unbounded"
      }
      data-glass-admission={
        budgetResolved ? (budgetActive ? "active" : "fallback") : "pending"
      }
      data-glass-backdrop={backdropKind ?? "unclassified"}
      data-glass-blur-px={resolvedBlur}
      data-glass-depth-px={settings.refraction === false ? 0 : resolvedDepth}
      data-glass-color-bleed={optical.colorBleed}
      data-glass-rendering={
        rendering === "composited"
          ? compositorReady
            ? "composited"
            : "lightweight"
