            ? "shared"
            : budgetActive
              ? "active"
              : "lightweight"
      }
      data-refraction={mode}
      style={{ borderRadius: safeRadius, ...style }}
    >
      {/* Each lens owns its housing. The manager retains at most two definitions. */}
      {rendering === "auto" && (
        <svg
          ref={housing}
          aria-hidden="true"
          width={0}
          height={0}
          style={{ position: "absolute", pointerEvents: "none" }}
        />
      )}
      {rendering !== "inherited" && (
        <div
          aria-hidden="true"
          data-glass-clip=""
          style={{
            position: "absolute",
            inset: 0,
            zIndex: -1,
            pointerEvents: "none",
            clipPath: lensClipPath(size.w, size.h, safeRadius, shape),
            isolation: "isolate",
            // A clipped element is a backdrop root. Put the ordinary CSS
            // fallback on this element, not inside its empty backdrop boundary.
            backdropFilter:
              rendering !== "composited" && !portable && !active && !reduced
                ? diffuse
                : "none",
            WebkitBackdropFilter:
              rendering !== "composited" && !portable && !active && !reduced
                ? diffuse
                : "none",
          }}
        >
          {/* Keep color finish outside the SVG; blur runs before its colored rim. */}
          {rendering !== "composited" && (
            <div
              data-glass-blur=""
              style={{
                position: "absolute",
                inset: -samplingPad,
                filter:
                  portable && !reduced
                    ? active
                      ? colorFinish
                      : diffuse
                    : undefined,
              }}
            >
              <div
                ref={layer}
                data-lens-layer=""
                className="glass-optical-layer"
                style={{
                  position: "absolute",
                  inset: 0,
                }}
              >
                {/* Clip the *source* before filtering so SourceGraphic is lens-sized,
              even if the bounded scene contains hundreds of DOM nodes. */}
                <div
                  data-glass-source-window=""
                  style={{
                    position: "absolute",
                    inset: 0,
                    overflow: "hidden",
                    contain: "paint",
                    backgroundImage:
                      plane && !reduced
                        ? `url(${JSON.stringify(plane.src)})`
                        : undefined,
                    backgroundSize: plane
                      ? `${plane.width}px ${plane.height}px`
                      : undefined,
                    backgroundPosition: plane
                      ? `${plane.x}px ${plane.y}px`
                      : undefined,
                    backgroundRepeat: "no-repeat",
                  }}
                >
                  <div
                    ref={mirrorHost}
                    data-glass-mirror-host=""
                    inert
                    style={{ position: "absolute", pointerEvents: "none" }}
                  />
                </div>
              </div>
            </div>
          )}
          <div
            data-glass-tint=""
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: reduced
                ? "var(--background, #f7f7f9)"
                : rgba(p.tintColor, p.tint),
              mixBlendMode: reduced ? "normal" : tintBlendMode,
            }}
          />
          {!reduced && readability && readability.opacity > 0 && (
            <div
              data-glass-readability=""
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: readability.color,
                opacity: readability.opacity,
              }}
            />
          )}
          {active && !reduced && textures?.reflection && (
            <div
              data-glass-reflection=""
              style={{
                ...textureStyle,
                backgroundImage: `url("${textures.reflection}")`,
                opacity: (p.glint / 100) * (1 - optical.colorBleed * 0.85),
              }}
            />
          )}
          {active && !reduced && textures?.shade && (
            <div
              style={{
                ...textureStyle,
                backgroundImage: `url("${textures.shade}")`,
              }}
            />
          )}
        </div>
      )}
      {rendering !== "inherited" &&
        (showOutline ?? settings.showOutlines) &&
        size.w > 0 &&
        size.h > 0 && (
          <svg
            data-glass-outline=""
            aria-hidden="true"
            viewBox={`0 0 ${size.w} ${size.h}`}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              overflow: "visible",
              pointerEvents: "none",
            }}
          >
            <path
              d={lensOutlinePath(size.w, size.h, safeRadius, shape)}
              fill="none"
              stroke="currentColor"
              strokeOpacity=".35"
              strokeWidth="1"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
        )}
      {asChild ? <Slot.Slottable>{children}</Slot.Slottable> : children}
    </Tag>
  );
}

export function LiquidButton({
