export function LiquidContextMenu({
  items,
  preset = "regular",
  config,
  className = "",
}: {
  items: { label: string; action: () => void; danger?: boolean }[];
  preset?: GlassPreset;
  config?: Partial<LensParams>;
  className?: string;
}) {
  return (
    <LiquidGlass
      preset={preset}
      config={config}
      radius={20}
