      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        1,
        1,
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        new Uint8Array([128, 128, 128, 255]),
      );
      return value;
    };
    this.video = texture();
    this.mapTextures = Array.from({ length: 4 }, texture);
    gl.uniform1i(gl.getUniformLocation(program, "videoFrame"), 0);
    for (let i = 0; i < 4; i++)
      gl.uniform1i(gl.getUniformLocation(program, `map${i}`), i + 1);
  }
  resize(width: number, height: number) {
    this.width = Math.max(1, width);
    this.height = Math.max(1, height);
    const dpr = Math.min(
      1.5,
      devicePixelRatio || 1,
      Math.sqrt(1_500_000 / (this.width * this.height)),
    );
    this.canvas.width = Math.round(this.width * dpr);
    this.canvas.height = Math.round(this.height * dpr);
    this.gl.viewport(0, 0, this.canvas.width, this.canvas.height);
  }
  async setLenses(lenses: VideoGlassLens[]) {
    const next = lenses.slice(0, 4),
      key = JSON.stringify(next);
    if (key === this.geometry) {
      await this.loading;
      return;
    }
    this.geometry = key;
    this.lenses = next;
    const revision = ++this.revision;
    this.metrics = next.flatMap((lens) => {
      const p = resolveControlLens(lens.parameters),
        m = controlLensMetrics(lens.width, lens.height, p);
      return [
        m.pad,
        m.maximum,
        lens.width + m.pad * 2,
        lens.height + m.pad * 2,
      ];
    });
    this.rectData.fill(0);
    this.mapData.fill(0);
    this.radiusData.fill(0);
    this.blurData.fill(0);
    next.forEach((lens, i) => {
      this.rectData.set([lens.x, lens.y, lens.width, lens.height], i * 4);
      this.mapData.set(this.metrics.slice(i * 4, i * 4 + 4), i * 4);
      this.radiusData[i] = lens.radius;
      this.blurData[i] = resolveControlLens(lens.parameters).blur;
    });
    const images = await (this.loading = Promise.all(
      next.map(async (lens) => {
        const p = resolveControlLens(lens.parameters),
          image = new Image();
        image.src = buildControlLensTextures(
          lens.width,
          lens.height,
          lens.radius,
          p,
        ).displacement;
        await image.decode();
        return image;
      }),
    ));
    if (this.disposed || revision !== this.revision) return;
    const gl = this.gl;
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    images.forEach((image, i) => {
      gl.activeTexture(gl.TEXTURE0 + i + 1);
      gl.bindTexture(gl.TEXTURE_2D, this.mapTextures[i]);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        image,
      );
    });
    this.canvas.dataset.lensMapRevisions = String(revision);
  }
  draw(source: HTMLVideoElement, refraction = true) {
    if (this.disposed || source.readyState < 2 || !source.videoWidth) return;
    this.imageSource = "";
    this.paint(source, source.videoWidth, source.videoHeight, refraction);
  }
  /** Static images use the very same shader, with a small aligned source window.
   * Their texture is uploaded on image change, never continuously while idle. */
  drawImage(
    source: HTMLImageElement,
    window: { x: number; y: number; width: number; height: number },
    refraction = true,
  ) {
    if (this.disposed || !source.complete || !source.naturalWidth) return;
    this.paint(source, source.naturalWidth, source.naturalHeight, refraction, window);
  }
  private paint(
    source: HTMLVideoElement | HTMLImageElement,
    sourceWidth: number,
    sourceHeight: number,
    refraction: boolean,
    window = { x: 0, y: 0, width: this.width, height: this.height },
  ) {
    const gl = this.gl,
      p = this.program;
    gl.useProgram(p);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.video);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    const imageKey = source instanceof HTMLImageElement ? source.currentSrc || source.src : "";
    if (!imageKey || imageKey !== this.imageSource) {
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
      this.imageSource = imageKey;
    }
    this.mapTextures.forEach((texture, i) => {
      gl.activeTexture(gl.TEXTURE0 + i + 1);
      gl.bindTexture(gl.TEXTURE_2D, texture);
    });
    const scale = Math.max(
      window.width / sourceWidth,
      window.height / sourceHeight,
    );
    gl.uniform2f(this.uniform("size"), this.width, this.height);
    gl.uniform2f(this.uniform("sourceSize"), window.width, window.height);
    gl.uniform2f(this.uniform("sourceOffset"), window.x, window.y);
    gl.uniform2f(
      this.uniform("crop"),
      window.width / (sourceWidth * scale),
      window.height / (sourceHeight * scale),
    );
    gl.uniform4fv(this.uniform("rects[0]"), this.rectData);
    gl.uniform4fv(this.uniform("maps[0]"), this.mapData);
    gl.uniform1fv(this.uniform("radii[0]"), this.radiusData);
    gl.uniform1fv(this.uniform("softness[0]"), this.blurData);
    gl.uniform1i(this.uniform("count"), this.lenses.length);
    gl.uniform1f(this.uniform("refraction"), refraction ? 1 : 0);
    gl.drawArrays(gl.TRIANGLES, 0, 6);
  }
  destroy() {
    this.disposed = true;
    this.revision++;
    const gl = this.gl;
    gl.deleteTexture(this.video);
    this.mapTextures.forEach((t) => gl.deleteTexture(t));
    gl.deleteBuffer(this.buffer);
    gl.deleteProgram(this.program);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  }
}

"use client";

import {
  createContext,
  useContext,
  useMemo,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
  type RefObject,
} from "react";
import type { LensParams, GlassOptics, GlassPreset } from "@/lib/glass";

export type GlassThemeBehavior = "unitheme" | "duotheme";

export interface GlassSettings {
  surface?: GlassPreset;
  /** Keeps finish and blur unchanged; switches only optical bending on/off. */
  refraction?: boolean;
  /** Diagnostic contour from the same geometry as the refracting mask. */
  showOutlines?: boolean;
  /** Unitheme adapts ink; duotheme keeps the supplied ink while material changes. */
  themeBehavior?: GlassThemeBehavior;
  config?: Partial<LensParams>;
  optics?: Partial<GlassOptics>;
  radius?: number;
  ink?: "auto" | "light" | "dark";
  contrastProtection?: boolean;
  performance?: { maxActiveSurfaces?: number; frameRate?: number };
}
const GlassSettingsContext = createContext<GlassSettings>({});
export function useGlassSettings() {
  return useContext(GlassSettingsContext);
}
/** Shared optical settings for components and portals, without another DOM layer. */
export function GlassSettingsProvider({
  children,
  surface,
  config,
  optics,
  radius,
  ink,
  contrastProtection,
  performance,
  themeBehavior,
  refraction,
  showOutlines,
}: GlassSettings & { children: ReactNode }) {
  const parent = useGlassSettings();
  const [initialInk] = useState<"light" | "dark">(
    ink === "light" ? "light" : "dark",
  );
  const behavior = themeBehavior ?? parent.themeBehavior ?? "unitheme";
  const selectedInk = ink ?? parent.ink;
  const resolvedInk =
    behavior === "duotheme" && (!selectedInk || selectedInk === "auto")
      ? initialInk
      : selectedInk;
  const value = useMemo(
    () => ({
      surface: surface ?? parent.surface,
      config: { ...parent.config, ...config },
      optics: { ...parent.optics, ...optics },
      radius: radius ?? parent.radius,
      ink: resolvedInk,
      themeBehavior: behavior,
      contrastProtection: contrastProtection ?? parent.contrastProtection,
      performance: { ...parent.performance, ...performance },
      refraction: refraction ?? parent.refraction ?? true,
      showOutlines: showOutlines ?? parent.showOutlines ?? false,
    }),
    [
      parent,
      surface,
      config,
      optics,
      radius,
      resolvedInk,
      behavior,
      contrastProtection,
      performance,
      refraction,
      showOutlines,
    ],
  );
  return (
    <GlassSettingsContext.Provider value={value}>
      {children}
    </GlassSettingsContext.Provider>
  );
}

export interface GlassSceneContextValue {
  source: RefObject<HTMLDivElement | null>;
  config?: Partial<LensParams>;
  frameRate?: number;
  appearance?: "light" | "dark";
  live?: boolean;
}
const GlassSceneContext = createContext<GlassSceneContextValue | null>(null);
export function useGlassScene() {
  return useContext(GlassSceneContext);
}

export interface GlassSceneProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "content"
> {
  /** The complete, interactive DOM backdrop. Lenses go in children. */
  content: ReactNode;
  sourceClassName?: string;
  /** Optional ref to the original scene, for contrast sampling or explicit invalidation. */
  sourceRef?: RefObject<HTMLDivElement | null>;
  config?: Partial<LensParams>;
  frameRate?: number;
  appearance?: "light" | "dark";
  /** Poll adaptive ink only for continuously animated or video sources. */
  live?: boolean;
}

/** One bounded source scene, shared by every descendant glass lens. */
export function GlassScene({
  content,
  children,
  sourceClassName,
  sourceRef,
  frameRate,
  config,
  appearance,
  live = false,
  style,
  ...props
}: GlassSceneProps) {
  const localSource = useRef<HTMLDivElement>(null);
  const source = sourceRef ?? localSource;
  const value = useMemo(
    () => ({ source, frameRate, config, appearance, live }),
    [source, frameRate, config, appearance, live],
  );
  return (
    <GlassSceneContext.Provider value={value}>
      <div
        {...props}
        data-glass-scene=""
        style={{ position: "relative", ...style }}
      >
        <div
          ref={source}
          data-glass-scene-source=""
          className={sourceClassName}
          style={{ position: "absolute", inset: 0 }}
        >
          {content}
        </div>
        {children}
      </div>
    </GlassSceneContext.Provider>
  );
}

"use client";

import { useEffect, useState, type RefObject } from "react";

export interface BackdropPlane {
  src: string;
  width: number;
  height: number;
  x: number;
  y: number;
}

/** Align an opt-in image backdrop to the glass in CSS pixels. Unlike SVG
 * backdrop-filter references, filtering an explicit source works in WebKit
 * and Gecko too. No DOM screenshots or asynchronous raster snapshots.
 */
export function useBackdropPlane(
  surface: RefObject<HTMLElement | null>,
  source: RefObject<HTMLImageElement | null> | undefined,
  pad: number,
): BackdropPlane | null {
  const [plane, setPlane] = useState<BackdropPlane | null>(null);
  useEffect(() => {
    const element = surface.current;
    const image = source?.current;
    if (!element || !image) return;
    let frame = 0;
    const update = () => {
      if (!image.complete || !image.naturalWidth) return;
      const imageRect = image.getBoundingClientRect();
      const glassRect = element.getBoundingClientRect();
      if (!imageRect.width || !imageRect.height) return;
      const style = getComputedStyle(image);
      const fit = style.objectFit;
      const cover = Math.max(
        imageRect.width / image.naturalWidth,
        imageRect.height / image.naturalHeight,
      );
      const contain = Math.min(
        imageRect.width / image.naturalWidth,
        imageRect.height / image.naturalHeight,
      );
      const scale =
        fit === "cover"
          ? cover
          : fit === "contain"
            ? contain
            : fit === "scale-down"
              ? Math.min(1, contain)
              : 1;
      const width =
        fit === "fill" ? imageRect.width : image.naturalWidth * scale;
      const height =
        fit === "fill" ? imageRect.height : image.naturalHeight * scale;
      const [horizontal = "50%", vertical = "50%"] =
        style.objectPosition.split(/\s+/);
      const position = (value: string, free: number) => {
        if (value === "center") return free / 2;
        if (value === "right" || value === "bottom") return free;
        if (value === "left" || value === "top") return 0;
        return value.endsWith("%")
          ? (free * parseFloat(value)) / 100
          : parseFloat(value) || 0;
      };
      const next = {
        src: image.currentSrc || image.src,
        width,
        height,
        x:
          imageRect.left -
          glassRect.left -
          element.clientLeft +
          pad +
          position(horizontal, imageRect.width - width),
        y:
          imageRect.top -
          glassRect.top -
          element.clientTop +
          pad +
          position(vertical, imageRect.height - height),
      };
      setPlane((previous) =>
        previous &&
        Object.keys(next).every(
          (key) =>
            previous[key as keyof BackdropPlane] ===
            next[key as keyof BackdropPlane],
        )
          ? previous
          : next,
      );
    };
    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(update);
    };
    const observer = new ResizeObserver(schedule);
    observer.observe(element);
    observer.observe(image);
    image.addEventListener("load", schedule);
    // Layout shifts and object-fit/source changes also alter the mapping.
    const mutations = new MutationObserver(schedule);
    mutations.observe(image, {
      attributes: true,
      attributeFilter: ["style", "class", "src", "srcset", "sizes"],
    });
    window.addEventListener("resize", schedule);
    window.addEventListener("scroll", schedule, {
      passive: true,
      capture: true,
    });
    update();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      mutations.disconnect();
      image.removeEventListener("load", schedule);
      window.removeEventListener("resize", schedule);
      window.removeEventListener("scroll", schedule, true);
    };
  }, [surface, source, pad]);
  return source ? plane : null;
}
